const rows = items[0].json.value;

/* =========================================================
   CONFIG
   Change to "Dayshift" or "Nightshift" depending on the flow
========================================================= */
const TARGET_SHIFT = "Nightshift"; // Or "Nightshift"
const SUMMARY_TITLE = `Daily EOD Summary - ${TARGET_SHIFT}`;

/* =========================================================
   HELPERS
========================================================= */
function clean(value) {
  return (value || "").toString().trim();
}

function getDateKey(date) {
  return date.toISOString().split('T')[0];
}

function formatDisplayDate(dateString) {
  if (!dateString) return "";
  const d = new Date(dateString);
  if (isNaN(d)) return "";
  return d.toLocaleDateString('en-GB', {
    day: '2-digit',
    month: 'short',
    year: 'numeric'
  });
}

function getSummaryDisplayDate() {
  return new Date().toLocaleDateString('en-GB', {
    day: '2-digit',
    month: 'long',
    year: 'numeric'
  });
}

/* =========================================================
   SHIFT DATE LOGIC
========================================================= */
const todayObj = new Date();
const todayKey = getDateKey(todayObj);

const yesterdayObj = new Date();
yesterdayObj.setDate(todayObj.getDate() - 1);
const yesterdayKey = getDateKey(yesterdayObj);

const SOD_TARGET_DATE = (TARGET_SHIFT === "Nightshift") ? yesterdayKey : todayKey;
const EOD_TARGET_DATE = todayKey;

/* =========================================================
   DATA PROCESSING STRUCTURE (Employee -> Team)
========================================================= */
const rawEmployeeGrouped = {};

for (const row of rows) {
  const item = row.fields;
  if (!item) continue;

  const shift = clean(item.Shift);
  if (shift !== TARGET_SHIFT) continue;

  const snapshotDate = clean(item.SnapshotDate).split('T')[0];
  const bucket = clean(item.SOD_x002f_EOD_x002f_BLOCKED).toUpperCase();

  if (bucket === "SOD" && snapshotDate !== SOD_TARGET_DATE) continue;
  if (bucket === "EOD" && snapshotDate !== EOD_TARGET_DATE) continue;
  if (bucket === "BLOCKED" && snapshotDate !== EOD_TARGET_DATE) continue; 
  if (bucket !== "SOD" && bucket !== "EOD" && bucket !== "BLOCKED") continue;

  const employee = clean(item.AssignedTo).replace(/,\s*$/, '') || "Unassigned";
  const team = clean(item.TeamName) || "None";
  const title = clean(item.Title) || "Untitled Task";
  const notes = clean(item.Notes);
  const dueDate = formatDisplayDate(item.DueDate);
  const delayed = clean(item.Is_x0020_Delayed).toLowerCase().includes("yes");

  const taskObject = { title, notes, dueDate, delayed };

  if (!rawEmployeeGrouped[employee]) rawEmployeeGrouped[employee] = {};
  if (!rawEmployeeGrouped[employee][team]) {
    rawEmployeeGrouped[employee][team] = { sod: [], eod: [], blocked: [] };
  }

  if (bucket === "SOD") rawEmployeeGrouped[employee][team].sod.push(taskObject);
  if (bucket === "EOD") rawEmployeeGrouped[employee][team].eod.push(taskObject);
  if (bucket === "BLOCKED") rawEmployeeGrouped[employee][team].blocked.push(taskObject);
}

/* =========================================================
   COMPUTE COMPLETED VS IN-PROGRESS PER TEAM
========================================================= */
const finalEmployeeGrouped = {};

for (const employee in rawEmployeeGrouped) {
  finalEmployeeGrouped[employee] = {};

  for (const team in rawEmployeeGrouped[employee]) {
    const { sod, eod, blocked } = rawEmployeeGrouped[employee][team];

    const completed = [];
    const inProgress = [];

    // 1. EOD is implicitly completed
    for (const eodTask of eod) {
      completed.push(eodTask);
    }

    // 2. SOD cross-referenced against EOD/Blocked to deduce progress
    for (const sodTask of sod) {
      const foundInEod = eod.some(eodTask => eodTask.title.toLowerCase() === sodTask.title.toLowerCase());
      const foundInBlocked = blocked.some(bTask => bTask.title.toLowerCase() === sodTask.title.toLowerCase());

      if (!foundInEod && !foundInBlocked) {
        inProgress.push(sodTask);
      }
    }

    if (completed.length > 0 || inProgress.length > 0 || blocked.length > 0) {
      finalEmployeeGrouped[employee][team] = { completed, inProgress, blocked };
    }
  }

  if (Object.keys(finalEmployeeGrouped[employee]).length === 0) {
    delete finalEmployeeGrouped[employee];
  }
}

/* =========================================================
   SORTING EMPLOYEES
========================================================= */
const sortedEmployees = Object.keys(finalEmployeeGrouped).sort((a, b) =>
  a.trim().toLowerCase().localeCompare(b.trim().toLowerCase())
);

/* =========================================================
   ADAPTIVE CARD GENERATION
========================================================= */
const cardBody = [];

// Header Info
cardBody.push({ type: "TextBlock", text: `📋 ${SUMMARY_TITLE}`, weight: "Bolder", size: "Large", wrap: true });
cardBody.push({ type: "TextBlock", text: `📅 ${getSummaryDisplayDate()}`, spacing: "Small", wrap: true });
cardBody.push({ type: "TextBlock", text: "", separator: true });

if (sortedEmployees.length === 0) {
  cardBody.push({ type: "TextBlock", text: "No shift updates found for today.", wrap: true });
}

// Helper task lines builder (FIXED: Stripped out markdown code-block space rules)
function buildTaskLines(tasks) {
  let lines = [];
  for (let i = 0; i < tasks.length; i++) {
    const task = tasks[i];
    let line = `${i + 1}. ${task.title}`;
    if (task.dueDate) line += ` | Due: ${task.dueDate}`;
    if (task.delayed) line += ` ⚠️`;
    if (task.notes) line += `\n↳ *Notes: ${task.notes}*`;
    lines.push(line);
  }
  return lines.join('\n\n');
}

/* =========================================================
   FLIPPED RENDERING
========================================================= */
for (const employee of sortedEmployees) {
  const employeeTeams = finalEmployeeGrouped[employee];

  // 1. Employee Header Name
  cardBody.push({ type: "TextBlock", text: `👤 ${employee}`, weight: "Bolder", size: "Medium", spacing: "Large", wrap: true });

  const sortedTeams = Object.keys(employeeTeams).sort((a, b) => {
    if (a === "None") return 1;
    if (b === "None") return -1;
    return a.localeCompare(b);
  });

  let hasEodUpdates = false;
  let hasBlockedUpdates = false;

  for (const team of sortedTeams) {
    if (employeeTeams[team].completed.length || employeeTeams[team].inProgress.length) hasEodUpdates = true;
    if (employeeTeams[team].blocked.length) hasBlockedUpdates = true;
  }

  // 2. Render EOD Updates block
  if (hasEodUpdates) {
    cardBody.push({ type: "TextBlock", text: "🔄 EOD Updates", weight: "Bolder", color: "Accent", spacing: "Small", wrap: true });

    for (const team of sortedTeams) {
      const { completed, inProgress } = employeeTeams[team];
      if (!completed.length && !inProgress.length) continue;

      cardBody.push({ type: "TextBlock", text: `🏢 *Team: ${team}*`, weight: "Bolder", spacing: "Small", wrap: true });

      if (completed.length) {
        cardBody.push({ type: "TextBlock", text: "✅ *Completed Tasks*:", spacing: "Small", wrap: true });
        cardBody.push({ type: "TextBlock", text: buildTaskLines(completed), wrap: true, spacing: "Small" });
      }

      if (inProgress.length) {
        cardBody.push({ type: "TextBlock", text: "⏳ *In Progress Tasks*:", spacing: "Small", wrap: true });
        cardBody.push({ type: "TextBlock", text: buildTaskLines(inProgress), wrap: true, spacing: "Small" });
      }
    }
  }

  // 3. Render Blocked Tasks block
  if (hasBlockedUpdates) {
    cardBody.push({ type: "TextBlock", text: "🚫 Blocked Tasks", weight: "Bolder", color: "Attention", spacing: "Medium", wrap: true });

    for (const team of sortedTeams) {
      const { blocked } = employeeTeams[team];
      if (!blocked.length) continue;

      cardBody.push({ type: "TextBlock", text: `🏢 *Team: ${team}*`, weight: "Bolder", spacing: "Small", wrap: true });
      cardBody.push({ type: "TextBlock", text: buildTaskLines(blocked), wrap: true, spacing: "Small" });
    }
  }
}

/* =========================================================
   FINAL OUTPUT PAYLOAD
========================================================= */
const payload = {
  subject: SUMMARY_TITLE,
  body: { contentType: "html", content: '<attachment id="1"></attachment>' },
  attachments: [
    {
      id: "1",
      contentType: "application/vnd.microsoft.card.adaptive",
      contentUrl: null,
      content: JSON.stringify({
        type: "AdaptiveCard",
        version: "1.4",
        $schema: "http://adaptivecards.io/schemas/adaptive-card.json",
        body: cardBody
      })
    }
  ]
};

return [{ json: { payload: JSON.stringify(payload) } }];
